1	package agentusage
2	
3	import (
4		"errors"
5		"io"
6		"os"
7		"time"
8	)
9	
10	// fileCursor is the read position of one transcript. Values only: no pointer
11	// except the immutable os.FileInfo.
12	type fileCursor struct {
13		path     string      // full path, never logged
14		name     string      // sanitized base name (FileIssue.File, TruncatedFiles)
15		agent    string      // sanitized agent ID; "" for the parent
16		rank     string      // position rank of the file (parentRank or transcriptRank)
17		id       os.FileInfo // from the open handle's Stat at the last read; nil before
18		offset   int64       // just past the last complete line folded in
19		size     int64       // file size at the last read
20		modTime  time.Time   // Lstat mtime at the last listing
21		skipFrom int64       // start of an oversized line still being written, or -1
22		tail     bool        // an incomplete line follows offset (TruncatedFiles)
23		issue    IssueKind   // state issue of the last read (D6), valid if hasIssue
24		issueOff int64
25		hasIssue bool
26	}
27	
28	// newFileCursor returns the cursor of a transcript not read yet.
29	func newFileCursor(path, name, agent, rank string) fileCursor {
30		return fileCursor{path: path, name: name, agent: agent, rank: rank, skipFrom: -1}
31	}
32	
33	// transcriptFile is what readFile needs from an open transcript; *os.File
34	// satisfies it.
35	type transcriptFile interface {
36		io.Reader
37		io.ReaderAt
38		io.Seeker
39		io.Closer
40		Stat() (os.FileInfo, error)
41	}
42	
43	// openTranscript opens a transcript through openPlain. A var so tests can
44	// count opens and bytes read.
45	var openTranscript = func(path string) (transcriptFile, error) {
46		f, err := openPlain(path, false)
47		if err != nil {
48			return nil, err
49		}
50		if f == nil {
51			return nil, errNotRegular
52		}
53		return f, nil
54	}
55	
56	// fileRead is the outcome of reading one file from its cursor.
57	type fileRead struct {
58		next  fileCursor
59		part  *table // lines folded from the new bytes; nil when nothing was read
60		reset bool   // not an append (D4): the caller restarts the whole session
61	}
62	
63	// read reports whether the cursor has already read part of its file.
64	func (fc fileCursor) read() bool { return fc.offset > 0 || fc.skipFrom >= 0 || fc.id != nil }
65	
66	// quiet reports whether the file is, as far as Lstat can tell, exactly what the
67	// last read saw. A cursor holding a read error never is: the bytes between
68	// its offset and the failure must be read again.
69	func (fc fileCursor) quiet(li os.FileInfo) bool {
70		if fc.id == nil || (fc.hasIssue && fc.issue == IssueReadError) {
71			return false
72		}
73		return li.Size() == fc.size && os.SameFile(li, fc.id)
74	}
75	
76	// failRead is the outcome of a path that cannot be read: a reset when the file
77	// was read before (D4), else a state issue cleared by the next success (D6).
78	func failRead(fc fileCursor) fileRead {
79		if fc.read() {
80			return fileRead{next: fc, reset: true}
81		}
82		fc.issue, fc.issueOff, fc.hasIssue = IssueOpenFailed, 0, true
83		return fileRead{next: fc}
84	}
85	
86	// isAppend reports whether the open file is the one fc read, only grown (D4).
87	func (fc fileCursor) isAppend(f transcriptFile, fi os.FileInfo) bool {
88		if (fc.id != nil && !os.SameFile(fi, fc.id)) || fi.Size() < fc.size {
89			return false
90		}
91		if fc.offset == 0 {
92			return true
93		}
94		var b [1]byte
95		n, _ := f.ReadAt(b[:], fc.offset-1)
96		return n == 1 && b[0] == '\n'
97	}
98	
99	// readFile reads what was appended to fc's file since fc. now clamps mtimes.
100	// It never follows a link and never opens a non-regular file.
101	func readFile(fc fileCursor, now time.Time) fileRead {
102		li, err := os.Lstat(fc.path)
103		if err != nil || !li.Mode().IsRegular() {
104			return failRead(fc)
105		}
106		fc.modTime = li.ModTime()
107		if fc.modTime.After(now) {
108			fc.modTime = now
109		}
110		if fc.quiet(li) {
111			return fileRead{next: fc}
112		}
113		f, err := openTranscript(fc.path)
114		if err != nil {
115			return failRead(fc)
116		}
117		defer func() { _ = f.Close() }()
118		fi, err := f.Stat()
119		if err != nil {
120			return failRead(fc)
121		}
122		if !fc.isAppend(f, fi) {
123			return fileRead{next: fc, reset: true}
124		}
125		return fc.scan(f, fi)
126	}
127	
128	// scan folds the lines past the cursor into a new table and returns the
129	// advanced cursor. A line held back is read again next time (D1); an
130	// oversized one still being written is resumed in skip mode (D2).
131	func (fc fileCursor) scan(f transcriptFile, fi os.FileInfo) fileRead {
132		start := fc.offset
133		if fc.skipFrom >= 0 {
134			start = fc.size
135		}
136		if _, err := f.Seek(start, io.SeekStart); err != nil {
137			return failRead(fc)
138		}
139		part := newTable()
140		res, err := scanFrom(f, start, fc.skipFrom, MaxLineBytes, func(line []byte, off int64) {
141			part.addLine(fc.agent, fc.name, pos{rank: fc.rank, off: off}, line)
142		})
143		for _, off := range res.OversizedAt {
144			part.addOversized(fc.name, pos{rank: fc.rank, off: off})
145		}
146		next := fc
147		next.id, next.size, next.skipFrom = fi, res.End, res.SkipFrom
148		next.offset, next.tail = res.Consumed, len(res.Tail) > 0
149		if fc.skipFrom >= 0 && res.Consumed == start {
150			next.offset = fc.offset // the oversized line has not ended yet
151		}
152		next.issue, next.issueOff, next.hasIssue = 0, 0, false
153		if err != nil {
154			next.issue, next.issueOff, next.hasIssue = IssueReadError, next.offset, true
155		}
156		return fileRead{next: next, part: part}
157	}
