161	// implementation, so the tests fail on assertions rather than on compilation.
162	
163	// ErrStaleDelta is returned by Apply for a delta that was not read from the
164	// aggregate's current cursor. The aggregate is unchanged; read again from
165	// Cursor().
166	var ErrStaleDelta = errors.New("agentusage: delta does not follow the aggregate's cursor")
