172	// Cursor records how far each file of one session has been read.
173	type Cursor struct{}
174	
175	// Rewound returns c with every position cleared, keeping its identity.
176	func (c Cursor) Rewound() Cursor { return c }
177	
178	// String redacts the paths the cursor holds.
179	func (c Cursor) String() string { return "" }
180	
181	// GoString redacts the paths the cursor holds.
182	func (c Cursor) GoString() string { return "" }
183	
184	// Delta is what ReadDelta found since a Cursor.
185	type Delta struct{}
186	
187	// Full reports whether the delta was read from the start of every file.
188	func (d Delta) Full() bool { return false }
189	
190	// Empty reports whether nothing changed.
191	func (d Delta) Empty() bool { return false }
192	
193	// String shows counts only.
194	func (d Delta) String() string { return "" }
195	
196	// GoString shows counts only.
197	func (d Delta) GoString() string { return "" }
198	
199	// ReadDelta lists the session again and reads what was appended since c.
200	func ReadDelta(c Cursor) (Delta, error) { return Delta{}, nil }
201	
202	// Aggregate is a session's usage built from successive deltas.
203	type Aggregate struct{ t *table }
204	
205	// NewAggregate starts an empty aggregate for the session whose parent
206	// transcript is parentTranscript. It does no I/O.
207	func NewAggregate(parentTranscript string) *Aggregate { return &Aggregate{t: newTable()} }
