57		}
58		id := strings.TrimSuffix(base, transcriptExt)
59		if id == "" {
60			return SessionFiles{}, fmt.Errorf("agentusage: %s has no session id", base)
61		}
62		files := SessionFiles{ID: sanitizeLabel(id), Parent: parentTranscript}
63		sessionDir := filepath.Join(filepath.Dir(parentTranscript), id)
64		if fi, err := os.Lstat(sessionDir); err != nil || !fi.IsDir() {
65			if err == nil || errors.Is(err, os.ErrNotExist) {
66				return files, nil // absent, or a link: no sub-agents
67			}
68			return files, baseOnly(err)
69		}
70		files.SubAgents, err = subAgentFiles(filepath.Join(sessionDir, subagentsDir))
71		return files, baseOnly(err)
72	}
73	
74	// subAgentFiles lists agent-<id>.jsonl files directly inside dir, sorted by
75	// ID, each with its meta file if one exists. A missing dir or a symbolic
76	// link yields nothing.
77	func subAgentFiles(dir string) ([]SubAgentFiles, error) {
78		f, err := openPlain(dir, true)
79		if f == nil {
80			if err == nil || errors.Is(err, os.ErrNotExist) {
81				return nil, nil
82			}
83			return nil, err
84		}
85		defer func() { _ = f.Close() }()
86		entries, err := f.ReadDir(-1)
87		if err != nil {
88			return nil, err
89		}
90		var out []SubAgentFiles
91		for _, e := range entries {
92			if sa, ok := subAgentEntry(dir, e); ok {
93				out = append(out, sa)
94			}
95		}
96		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
97		return out, nil
98	}
99	
100	// subAgentEntry turns a directory entry into a sub-agent, if it is a
101	// regular agent-<id>.jsonl file.
102	func subAgentEntry(dir string, e os.DirEntry) (SubAgentFiles, bool) {
103		name := e.Name()
104		if !e.Type().IsRegular() || !strings.HasPrefix(name, agentPrefix) || !strings.HasSuffix(name, transcriptExt) {
105			return SubAgentFiles{}, false
106		}
107		id := strings.TrimSuffix(strings.TrimPrefix(name, agentPrefix), transcriptExt)
108		if id == "" {
109			return SubAgentFiles{}, false
110		}
111		sa := SubAgentFiles{ID: sanitizeLabel(id), Transcript: filepath.Join(dir, name)}
112		metaPath := filepath.Join(dir, agentPrefix+id+metaExt)
113		if mf, _ := openPlain(metaPath, false); mf != nil {
114			_ = mf.Close()
115			sa.Meta = metaPath
116		}
117		return sa, true
118	}
119	
120	// baseOnly rewrites a path error so it names the base name of the file, not
121	// the full path; errors.Is and errors.As on the cause keep working.
122	func baseOnly(err error) error {
123		var pe *fs.PathError
124		if errors.As(err, &pe) {
125			return &fs.PathError{Op: pe.Op, Path: filepath.Base(pe.Path), Err: pe.Err}
126		}
127		return err
128	}
