201	// cloneSession copies a fixture session under a temp dir, keeping its session
202	// id. Transcripts are created empty and returned as sources when empty is
203	// set, written whole otherwise; meta files are always written whole.
204	func cloneSession(t *testing.T, files SessionFiles, empty bool) (*sess, []src) {
205		t.Helper()
206		s := newSess(t)
207		s.uuid = strings.TrimSuffix(filepath.Base(files.Parent), transcriptExt)
208		read := func(p string) []byte {
209			b, err := os.ReadFile(p)
210			if err != nil {
211				t.Fatal(err)
212			}
213			return b
214		}
215		var srcs []src
216		place := func(from, to string) {
217			data := read(from)
218			if empty {
219				s.put(to, nil)
220				srcs = append(srcs, src{to, data})
221				return
222			}
223			s.put(to, data)
224		}
225		place(files.Parent, s.parent())
226		for _, sa := range files.SubAgents {
227			place(sa.Transcript, s.sub(sa.ID))
228			if sa.Meta != "" {
229				s.put(s.metaPath(sa.ID), read(sa.Meta))
230			}
231		}
232		return s, srcs
233	}
