235	// nextChunk returns the end of the chunk of data starting at off: size bytes,
236	// or through the next newline when size is 0.
237	func nextChunk(data []byte, off, size int) int {
238		if size > 0 {
239			return min(off+size, len(data))
240		}
241		if i := bytes.IndexByte(data[off:], '\n'); i >= 0 {
242			return off + i + 1
243		}
244		return len(data)
245	}
