249	// Fixtures rebuilt chunk by chunk, files interleaved round-robin, one
250	// ReadDelta + Apply after every chunk: the result is ParseSession's.
251	func TestReadDeltaEquivalenceFixtures(t *testing.T) {
252		chunkings := []struct {
253			name string
254			size int // 0: line by line
255		}{{"1 byte", 1}, {"7 bytes", 7}, {"64 bytes", 64}, {"4096 bytes", 4096}, {"line by line", 0}}
256		for _, name := range []string{"v2.1.302-basic", "synthetic-other-version", "damaged"} {
257			for _, ck := range chunkings {
258				t.Run(name+"/"+ck.name, func(t *testing.T) {
259					orig := fixtureSession(t, name)
260					s, srcs := cloneSession(t, orig, true)
261					a := NewAggregate(s.parent())
262					if d := readApply(t, a); !d.Full() {
263						t.Error("first delta: Full = false, want true")
264					}
265					offs := make([]int, len(srcs))
266					for pending := true; pending; {
267						pending = false
268						for i, sr := range srcs {
269							if offs[i] >= len(sr.data) {
270								continue
271							}
272							pending = true
273							end := nextChunk(sr.data, offs[i], ck.size)
274							appendFile(t, sr.path, sr.data[offs[i]:end])
275							offs[i] = end
276							readApply(t, a)
277							if ck.size != 1 { // the 1-byte run is checked at the end only
278								assertMatchesParse(t, a, s)
279							}
280							if t.Failed() {
281								t.Fatalf("diverged after %d bytes of %s", end, filepath.Base(sr.path))
282							}
283						}
284					}
285					assertMatchesParse(t, a, s)
286					want, err := ParseSession(orig)
287					if err != nil {
288						t.Fatal(err)
289					}
290					assertSameUsage(t, a.Usage(), want)
291					if name == "v2.1.302-basic" {
292						// hand-written totals of TestParseSessionBasic, summed
293						if got, want := a.Usage().Total(), (Tokens{33, 588, 4640, 1560}); got != want {
294							t.Errorf("Total = %+v, want %+v", got, want)
295						}
296					}
297				})
298			}
299		}
300	}
