302	// randomLines builds the content of one random transcript: repeated ids (also
303	// across files), lines without id, bad and blank lines, and sometimes a last
304	// line that is still being written.
305	func randomLines(rng *rand.Rand) []byte {
306		pool := []string{"m1", "m2", "m3", "m4", "m5"}
307		stops := []string{"end_turn", "", "tool_use"}
308		var buf bytes.Buffer
309		for n := rng.Intn(12); n > 0; n-- {
310			switch rng.Intn(10) {
311			case 0:
312				buf.WriteString("not json {{{\n")
313			case 1:
314				buf.WriteString("\n")
315			case 2, 3:
316				buf.Write(msgLine("", "claude-n", stops[rng.Intn(3)], int64(rng.Intn(9)), 1, 2, 3))
317				buf.WriteByte('\n')
318			default:
319				buf.Write(msgLine(pool[rng.Intn(len(pool))], "claude-"+strconv.Itoa(rng.Intn(3)),
320					stops[rng.Intn(3)], int64(rng.Intn(50)), int64(rng.Intn(50)), int64(rng.Intn(50)), int64(rng.Intn(50))))
321				buf.WriteByte('\n')
322			}
323		}
324		if rng.Intn(3) == 0 {
325			whole := msgLine("m9", "claude-0", "end_turn", 1, 1, 1, 1)
326			buf.Write(whole[:1+rng.Intn(len(whole)-1)])
327		}
328		return buf.Bytes()
329	}
