410	// Criterion 2 at session level: 6 MiB of parent and two sub-agents, one line
411	// appended to one of them: about that line is read, and nothing else opened.
412	func TestReadDeltaVolumeIsTheAppendedBytes(t *testing.T) {
413		s := newSess(t)
414		var buf bytes.Buffer
415		for i := 0; buf.Len() < 6<<20; i++ {
416			buf.Write(ln(fmt.Sprintf("old-%d", i)))
417		}
418		s.put(s.parent(), buf.Bytes())
419		s.put(s.sub("b1"), ln("s1"))
420		s.put(s.sub("b2"), ln("s2"))
421		p := countOpens(t)
422		a := NewAggregate(s.parent())
423		readApply(t, a)
424	
425		extra := ln("s3")
426		s.add(s.sub("b2"), extra)
427		*p = probe{}
428		d := readApply(t, a)
429		if d.Full() || d.Empty() {
430			t.Errorf("Full=%v Empty=%v, want a partial, non-empty delta", d.Full(), d.Empty())
431		}
432		if limit := int64(len(extra)) + 1; p.bytes > limit {
433			t.Errorf("bytes read = %d, want <= %d", p.bytes, limit)
434		}
435		if n := p.perPath[s.parent()] + p.perPath[s.sub("b1")]; n != 0 {
436			t.Errorf("the parent and the other sub-agent were opened %d times, want 0", n)
437		}
438		if got := agentByID(t, a.Usage(), "b2").Messages; got != 2 {
439			t.Errorf("b2 messages = %d, want 2", got)
440		}
441	}
