443	// Criterion 1: nothing written means no transcript opened, no meta read, and
444	// every delta empty.
445	func TestReadDeltaQuietSessionReadsNothing(t *testing.T) {
446		s := newSess(t)
447		s.put(s.parent(), cat(ln("p1"), ln("p2")))
448		for _, id := range []string{"a1", "b2", "c3"} {
449			s.put(s.sub(id), ln("s-"+id))
450			s.putMeta(id, metaUnfinished, time.Minute)
451		}
452		p := countOpens(t)
453		metas := countMetaReads(t)
454		a := NewAggregate(s.parent())
455		first := readApply(t, a)
456		if !first.Full() || first.Empty() {
457			t.Fatalf("first delta: Full=%v Empty=%v, want true and false", first.Full(), first.Empty())
458		}
459		if p.perPath[s.parent()] != 1 || *metas != 3 {
460			t.Fatalf("first read: parent opens %d, meta reads %d, want 1 and 3", p.perPath[s.parent()], *metas)
461		}
462		want := a.Usage()
463		*p, *metas = probe{}, 0
464		for i := 0; i < 5; i++ {
465			d := readApply(t, a)
466			if !d.Empty() || d.Full() {
467				t.Fatalf("pass %d: Empty=%v Full=%v, want true and false", i, d.Empty(), d.Full())
468			}
469		}
470		if p.calls != 0 || *metas != 0 {
471			t.Errorf("a quiet session: %d transcript open calls, %d meta reads, want 0 and 0", p.calls, *metas)
472		}
473		assertSameUsage(t, a.Usage(), want)
474	}
