476	// What makes a delta Empty or Full.
477	func TestDeltaEmptyAndFull(t *testing.T) {
478		tests := []struct {
479			name   string
480			mutate func(t *testing.T, s *sess)
481			empty  bool
482			full   bool
483		}{
484			{"nothing", func(*testing.T, *sess) {}, true, false},
485			{"mtime only", func(t *testing.T, s *sess) {
486				at := time.Now().Add(-time.Minute)
487				if err := os.Chtimes(s.parent(), at, at); err != nil {
488					t.Fatal(err)
489				}
490			}, true, false},
491			{"line appended to the parent", func(_ *testing.T, s *sess) { s.add(s.parent(), ln("p2")) }, false, false},
492			{"line appended to a sub-agent", func(_ *testing.T, s *sess) { s.add(s.sub("b1"), ln("s2")) }, false, false},
493			{"sub-agent appears", func(_ *testing.T, s *sess) { s.add(s.sub("a0"), ln("n1")) }, false, false},
494			{"sub-agent disappears", func(t *testing.T, s *sess) {
495				for _, p := range []string{s.sub("b1"), s.metaPath("b1")} {
496					if err := os.Remove(p); err != nil {
497						t.Fatal(err)
498					}
499				}
