1023		case len(u.Agents) == 0 || len(u.Agents[0].Models) == 0:
1024			t.Fatal("setup: no model on the first agent")
1025		case len(u.Diagnostics.Files) == 0 || len(u.Diagnostics.TruncatedFiles) == 0 || len(u.Versions) == 0:
1026			t.Fatalf("setup: files %d, truncated %d, versions %d, want all non-empty",
1027				len(u.Diagnostics.Files), len(u.Diagnostics.TruncatedFiles), len(u.Versions))
1028		}
1029		u.Agents[0].Models[0] = "MUTATED"
1030		u.Agents[0].Tokens.Input = -1
1031		u.Diagnostics.Files[0].File = "MUTATED"
1032		u.Diagnostics.TruncatedFiles[0] = "MUTATED"
1033		u.Versions[0] = "MUTATED"
1034		u.Agents = append(u.Agents[:1], u.Agents[1:]...)
1035		assertSameUsage(t, a.Usage(), want)
1036		// And a later Apply does not write through a Usage handed out before.
1037		first := a.Usage()
1038		s.add(s.parent(), ln("later"))
1039		readApply(t, a)
1040		assertSameUsage(t, first, want)
1041	}
1042	
1043	// --- privacy ----------------------------------------------------------------------
1044	
1045	func TestIncrementalNeverLeaksPathsOrContent(t *testing.T) {
1046		const sentinel = "SENTINEL-DO-NOT-LEAK"
1047		s, _ := cloneSession(t, fixtureSession(t, "damaged"), false)
1048		s2 := newSessIn(t, sentinel+"-dir")
1049		s2.uuid = s.uuid
1050		s2.put(s2.parent(), mustRead(t, s.parent()))
1051		s2.put(s2.sub("d1"), mustRead(t, s.sub("d1")))
1052		s2.put(s2.metaPath("d1"), mustRead(t, s.metaPath("d1")))
1053	
1054		a := NewAggregate(s2.parent())
1055		d1 := readApply(t, a)
1056		s2.add(s2.parent(), mustRead(t, s.parent())) // more sentinel content
1057		d2 := readApply(t, a)
1058		c := a.Cursor()
1059	
1060		var out strings.Builder
1061		for _, v := range []any{c, c.Rewound(), d1, d2} {
1062			fmt.Fprintf(&out, "%v %+v %#v %s\n", v, v, v, v)
1063		}
1064		fmt.Fprintf(&out, "%+v\n", a.Usage())
1065		if err := os.Remove(s2.parent()); err != nil {
1066			t.Fatal(err)
1067		}
1068		_, err := ReadDelta(a.Cursor())
1069		if err == nil {
1070			t.Fatal("ReadDelta on a deleted parent: err = nil")
1071		}
1072		fmt.Fprintf(&out, "%v %+v\n", err, err)
1073		text := out.String()
1074		for _, bad := range []string{sentinel, s2.dir, os.TempDir() + string(filepath.Separator)} {
1075			if strings.Contains(text, bad) {
1076				t.Errorf("output leaks %q:\n%s", bad, text)
1077			}
1078		}
1079		if text == "" || strings.TrimSpace(c.String()) == "" {
1080			t.Error("a redacted value must still print something")
1081		}
1082	}
1083	
1084	func mustRead(t *testing.T, path string) []byte {
1085		t.Helper()
1086		b, err := os.ReadFile(path)
1087		if err != nil {
1088			t.Fatal(err)
1089		}
1090		return b
1091	}
1092	
1093	func TestCursorAndDeltaStringsAreRedacted(t *testing.T) {
1094		s := newSess(t)
1095		s.put(s.parent(), ln("p1"))
1096		s.put(s.sub("b1"), ln("s1"))
1097		s.put(s.sub("b2"), ln("s2"))
1098		a := NewAggregate(s.parent())
1099		d := readApply(t, a)
1100		c := a.Cursor()
1101		const want = "agentusage.Cursor{files: 3}"
1102		if got := c.String(); got != want {
1103			t.Errorf("Cursor.String = %q, want %q", got, want)
1104		}
1105		if got := c.GoString(); got != want {
1106			t.Errorf("Cursor.GoString = %q, want %q", got, want)
1107		}
1108		for name, got := range map[string]string{"String": d.String(), "GoString": d.GoString()} {
1109			if got == "" || strings.Contains(got, s.dir) {
1110				t.Errorf("Delta.%s = %q: must be non-empty and hold no directory", name, got)
1111			}
1112		}
1113	}
1114	
1115	// --- TOCTOU at session level -------------------------------------------------------
1116	
1117	// A transcript swapped for another file between the listing and the open is
1118	// not an append: the delta is a Full one and the result is ParseSession's.
1119	func TestReadDeltaSwappedHandleTriggersAFullRead(t *testing.T) {
1120		s := newSess(t)
1121		s.put(s.parent(), ln("p1"))
1122		s.put(s.sub("b1"), cat(ln("s1"), ln("s2")))
1123		a := NewAggregate(s.parent())
1124		readApply(t, a)
1125	
1126		s.add(s.sub("b1"), ln("s3")) // grown: it will be opened
1127		other := filepath.Join(s.dir, "other.jsonl")
1128		s.put(other, cat(ln("x1"), ln("x2"), ln("x3"), ln("x4")))
1129		orig := openTranscript
1130		swapped := false
1131		swapOpen(t, func(path string) (transcriptFile, error) {
1132			if path == s.sub("b1") && !swapped {
1133				swapped = true
1134				return orig(other)
1135			}
1136			return orig(path)
1137		})
1138		d := readApply(t, a)
1139		if !swapped {
1140			t.Fatal("setup: the swap never fired")
1141		}
1142		if !d.Full() {
1143			t.Error("Full = false, want true: the handle was another file")
1144		}
1145		assertMatchesParse(t, a, s)
1146	}
1147	
1148	// --- the no-id cap across deltas (declared exception to D3) --------------------------
1149	
1150	// aggEntries is the number of per-message entries the aggregate holds.
1151	func aggEntries(a *Aggregate) int {
1152		if a.t == nil {
1153			return 0
1154		}
1155		return len(a.t.entries)
1156	}
1157	
1158	// merge folds deltas without the arrival-order cap a single read applies, so
1159	// the aggregate itself must keep the memory bound: after N deltas of lines
1160	// without id the table holds at most maxNoIDEntries entries, and the totals
1161	// are still exact (a spilled line counts, it just has no entry). Which lines
1162	// are the ones spilled follows arrival order: the declared exception to D3.
1163	func TestAggregateBoundsNoIDEntriesAcrossDeltas(t *testing.T) {
1164		s := newSess(t)
1165		const perDelta, deltas = 35000, 3 // 105000 > maxNoIDEntries
1166		total := perDelta * deltas
1167		if total <= maxNoIDEntries {
1168			t.Fatal("setup: not enough lines to pass the cap")
1169		}
1170		batch := bytes.Repeat(append(msgLine("", "m", "end_turn", 1, 0, 0, 0), '\n'), perDelta)
1171		s.put(s.parent(), nil)
1172		a := NewAggregate(s.parent())
1173		for i := 0; i < deltas; i++ {
1174			s.add(s.parent(), batch)
1175			readApply(t, a)
1176		}
1177		u := a.Usage()
1178		if len(u.Agents) == 0 || u.Agents[0].Messages != total || u.Agents[0].Tokens.Input != int64(total) || u.Diagnostics.NoMessageID != total {
1179			t.Fatalf("totals: agents %+v, NoMessageID %d, want %d lines counted once each", u.Agents, u.Diagnostics.NoMessageID, total)
1180		}
1181		if n := aggEntries(a); n > maxNoIDEntries {
1182			t.Errorf("entries = %d, want <= %d", n, maxNoIDEntries)
1183		}
1184		assertMatchesParse(t, a, s) // same totals as one sequential read
1185	}
1186	
1187	// --- issues are states carried by the cursors (D6) ------------------------------------
1188	
1189	func TestSessionIssuesComeFromCursorsAndClear(t *testing.T) {
1190		t.Run("open failure of a sub-agent", func(t *testing.T) {
1191			s := newSess(t)
1192			s.put(s.parent(), ln("p1"))
1193			s.put(s.sub("b1"), ln("s1"))
1194			a := NewAggregate(s.parent())
1195			readApply(t, a)
1196	
1197			s.add(s.sub("b1"), ln("s2")) // grown, so it is opened and the open fails
1198			orig := openTranscript
1199			swapOpen(t, func(path string) (transcriptFile, error) {
1200				if path == s.sub("b1") {
1201					return nil, os.ErrPermission
1202				}
1203				return orig(path)
1204			})
1205			if d := readApply(t, a); !d.Full() {
1206				t.Error("a file read before that cannot be opened: Full = false, want true")
1207			}
1208			u := a.Usage()
1209			if !hasIssue(u, "agent-b1.jsonl", IssueOpenFailed) {
1210				t.Errorf("no IssueOpenFailed for agent-b1.jsonl in %+v", u.Diagnostics.Files)
1211			}
1212			if got := agentByID(t, u, "b1"); got.Messages != 0 || got.Tokens != (Tokens{}) {
1213				t.Errorf("b1 = %+v, want no tokens while it cannot be opened", got)
1214			}
1215			if got := mainMessages(t, u); got != 1 {
1216				t.Errorf("parent messages = %d, want 1 (the restart must not lose or double it)", got)
1217			}
1218	
1219			openTranscript = orig // the file can be opened again
1220			readApply(t, a)
1221			if hasIssue(a.Usage(), "agent-b1.jsonl", IssueOpenFailed) {
1222				t.Errorf("IssueOpenFailed still there after a successful read: %+v", a.Usage().Diagnostics.Files)
1223			}
1224			if got := agentByID(t, a.Usage(), "b1").Messages; got != 2 {
1225				t.Errorf("b1 messages = %d, want 2", got)
1226			}
1227			assertMatchesParse(t, a, s)
1228		})
1229		t.Run("read error in the parent", func(t *testing.T) {
1230			s := newSess(t)
1231			l := int64(len(ln("a")))
1232			s.put(s.parent(), cat(ln("a"), ln("b"), ln("c")))
1233			faultFirstOpen(t, 2*l+l/2)
1234			a := NewAggregate(s.parent())
1235			readApply(t, a)
1236			u := a.Usage()
1237			var found bool
1238			for _, fi := range u.Diagnostics.Files {
1239				if fi.Kind == IssueReadError && fi.File == incSessUUID+".jsonl" && fi.Offset == 2*l {
1240					found = true
1241				}
1242			}
1243			if !found {
1244				t.Errorf("no IssueReadError at %d in %+v", 2*l, u.Diagnostics.Files)
1245			}
1246			if len(u.Agents) == 0 || u.Agents[0].Messages != 2 {
1247				t.Errorf("agents = %+v, want the two lines before the error", u.Agents)
1248			}
1249	
1250			d := readApply(t, a) // the file did not change, the bytes are read again
1251			if d.Empty() {
1252				t.Error("Empty = true after a read error: the missing bytes must be read again")
1253			}
1254			for _, fi := range a.Usage().Diagnostics.Files {
1255				if fi.Kind == IssueReadError {
1256					t.Errorf("IssueReadError still there after a clean read: %+v", fi)
1257				}
1258			}
1259			assertMatchesParse(t, a, s)
1260			if got := mainMessages(t, a.Usage()); got != 3 {
1261				t.Errorf("messages = %d, want 3, each counted once", got)
1262			}
1263		})
1264	}
