		p := countOpens(t)
		if _, err := ParseSession(files); err != nil {
			t.Fatal(err)
		}
		if want := 1 + len(files.SubAgents); p.calls != want {
			t.Errorf("openTranscript calls = %d, want %d", p.calls, want)
		}
