		swapOpen(t, func(string) (transcriptFile, error) { return nil, os.ErrPermission })
		u, err := ParseSession(files)
		if !errors.Is(err, os.ErrPermission) {
			t.Errorf("err = %v, want os.ErrPermission", err)
