				bad = sa.Transcript
			}
		}
		orig := openTranscript
		swapOpen(t, func(path string) (transcriptFile, error) {
			if path == bad {
				return nil, os.ErrPermission
			}
			return orig(path)
		})
		u, err := ParseSession(files)
