// faultyFile fails with errFault once limit bytes were delivered through Read.
type faultyFile struct {
	transcriptFile
	limit, n int64
}

func (f *faultyFile) Read(b []byte) (int, error) {
	if f.n >= f.limit {
		return 0, errFault
